using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitCommandHoldingTests
{
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:unit-held/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static WorldSession Ready(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+30000,a.Y+16000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);return s;}
    static long ArmyEnd(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.Max(r=>r.LastOrDefault()?.EndAt??s.Seconds);
    static WorldSession Failed(bool known=true,bool policy=true){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.RemoteRecall) with{OriginalPolicy=policy?NewGameMilitary.UnitCommandHoldingContract:null},s.PlayerControl,s.Revision).Code);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();At(s,d.DueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().Delivered);if(known)At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt);return s;}
    static WorldSession HomeReady(){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,Math.Max(ArmyEnd(s),j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);return s;}
    static TroopDispatch Query(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();
    static TroopReceipt Answer(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Receipts.Last();
    static UnitPostInquiryAnswer Quote(ContractWorld w){var r=w.NewMilitary!.UnitInquiry!.Receipts.Last();return ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body));}
    static void Ask(WorldSession s,NewMilitaryAction action=NewMilitaryAction.InquireUnitKnown,bool policy=true){var r=s.DecideNewMilitary(Input(s,action) with{PostPolicy=policy?NewGameMilitary.UnitReplyRecoveryContract:null},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void MoveAway(WorldSession s){var home=NewGameMilitary.Home(s.DiagnosticSnapshot(),0);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(home.X+5000,home.Y)},s.PlayerControl,s.Revision).Code);}
    static WorldSession FailedReply(bool policy=true){var s=Ready();Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Ask(s,policy:policy);At(s,Query(s).DueAt);MoveAway(s);At(s,Answer(s).ReplyDueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Replies.Last().Received);return s;}
    static void AtPersonEnd(WorldSession s){var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);}
    static void WalkTo(WorldSession s,FieldPoint p){Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=p},s.PlayerControl,s.Revision).Code);AtPersonEnd(s);}
    static WorldSession AtHeldOriginal(bool retryFirst=false){var s=FailedReply();var report=s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Single();if(retryFirst)Send(s,NewMilitaryAction.PersonalHome);At(s,report.DueAt);if(retryFirst)At(s,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Last().DueAt);WalkTo(s,Query(s).Destination);return s;}
    static WorldSession AtMissedReport(){var s=HomeReady();Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+5000,a.Y),B=new(a.X+5000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);long start=s.Seconds;Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.CombatStart) with{MotionContract=NewGameMilitary.RoutContract},s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);var w=s.DiagnosticSnapshot();var known=w.NewMilitary!.Withdrawal!.Sightings.Last().Position;var path=RegionalGround.Plan(NewGameMilitary.PersonPosition(w,s.Seconds),known,s.Seconds,courier:true,atlas:true);long delay=Math.Max(1,(path.LastOrDefault()?.EndAt??s.Seconds)-s.Seconds);long send=start+9-delay;Assert.True(send>=s.Seconds,"fixture must reach home before the last pre-rout inquiry window");At(s,send);Ask(s);At(s,Query(s).DueAt);Assert.True(Answer(s).Delivered);MoveAway(s);At(s,Answer(s).ReplyDueAt);var report=Assert.Single(s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights);At(s,report.DueAt);var journey=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,Math.Max(s.Seconds,(journey.Route.LastOrDefault()?.EndAt??s.Seconds)+1));return s;}
    static TroopDispatch Original(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();
    static WorldSession MissedFailureReport(){var s=Failed(false);var r=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single();MoveAway(s);At(s,r.ReplyDueAt);AtPersonEnd(s);return s;}
    [Fact]public void FailedOriginalPhysicallyReturnsWithoutReceiptOrEffect(){var s=Failed();var w=s.DiagnosticSnapshot();var d=Original(s);var h=Assert.Single(w.NewMilitary!.CommandHolding!.Holdings);Assert.Equal(d.Attempt,h.Attempt);Assert.Equal(NewGameMilitary.Home(w,0),h.Position);Assert.True(MessageFlow.FailureKnown(w.Messaging,d.Attempt,w.PlayerControl.Value));Assert.DoesNotContain(w.Messaging.Receipts,a=>a.MessageId==d.Message);Assert.False(w.NewMilitary.Withdrawal!.Receipts.Single().Delivered);Assert.False(w.NewMilitary.Withdrawal.Receipts.Single().Applied);Assert.Equal(h.Holder,Assert.Single(NewGameMilitary.CourierFrames(w,s.Seconds)).Carrier);}
    [Fact]public void MissedFailureReportAndOriginalHaveOneActualHolder(){var s=MissedFailureReport();var w=s.DiagnosticSnapshot();var rows=w.NewMilitary!.CommandHolding!.Holdings;Assert.Equal(2,rows.Length);Assert.Single(rows.Select(h=>h.Holder).Distinct());Assert.Single(rows.Select(h=>h.Position).Distinct());Assert.False(MessageFlow.FailureKnown(w.Messaging,Original(s).Attempt,w.PlayerControl.Value));Assert.Single(NewGameMilitary.CourierFrames(w,s.Seconds));}
    [Fact]public void ActualFailureReportPickupDoesNotDeliverOriginalOrder(){var s=MissedFailureReport();Send(s,NewMilitaryAction.PersonalHome);AtPersonEnd(s);int orders=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Send(s,NewMilitaryAction.TakeHeldReply);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var w=s.DiagnosticSnapshot();Assert.True(MessageFlow.FailureKnown(w.Messaging,Original(s).Attempt,w.PlayerControl.Value));Assert.DoesNotContain(w.Messaging.Receipts,a=>a.MessageId==Original(s).Message);Assert.Equal(orders,w.NewMilitary!.Orders.Length);Assert.Single(NewGameMilitary.HeldPapers(w,s.Seconds));}
    [Fact]public void FreshRetryAndRetainedOriginalHaveDistinctCarriers(){var s=Failed();Send(s,NewMilitaryAction.RetryRecallHome);var w=s.DiagnosticSnapshot();Assert.Equal(2,NewGameMilitary.CourierFrames(w,s.Seconds).Length);Assert.Equal(2,NewGameMilitary.CourierFrames(w,s.Seconds).Select(f=>f.Carrier).Distinct().Count());var d=w.NewMilitary!.UnitRetry!.Dispatches.Single();At(s,d.DueAt);w=s.DiagnosticSnapshot();Assert.Single(w.Messaging.Receipts,a=>a.MessageId==Original(s).Message);Assert.Single(NewGameMilitary.HeldPapers(w,s.Seconds));Assert.False(w.NewMilitary!.Withdrawal!.Receipts.Single().Delivered);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ReturnAndRetentionRestoreIdenticalFuture(int phase){var s=Failed(false);var r=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single();if(phase>0)At(s,phase==1?Math.Max(s.Seconds,r.ReplyDueAt-1):r.ReplyDueAt);var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));foreach(var x in new[]{s,c})At(x,r.ReplyDueAt+3);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedOrMissingOriginalCustodyIsRejected(int kind){var s=Failed();var w=s.DiagnosticSnapshot();var x=w.NewMilitary!.CommandHolding!;if(kind==0)x.Holdings[0]=x.Holdings[0] with{Position=new(0,0)};if(kind==1)x.Holdings[0]=x.Holdings[0] with{Attempt="fake"};if(kind==2)w.NewMilitary=w.NewMilitary with{CommandHolding=x with{Holdings=[]}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OldOriginalPolicyDoesNotGainRetainedPaperRetroactively(){var s=Failed(policy:false);var w=s.DiagnosticSnapshot();Assert.Null(w.NewMilitary!.CommandHolding);string json=System.Text.Encoding.UTF8.GetString(ContractJson.Write(w));Assert.DoesNotContain("OriginalPolicy",json);Assert.DoesNotContain("HoldingPolicy",json);Assert.DoesNotContain("CommandHolding",json);Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(new WorldSession(ContractJson.Copy(w)).DiagnosticSnapshot()));}
    [Fact]public void RetainedReportCannotBePickedUpFromRemoteLocation(){var s=MissedFailureReport();var w=s.DiagnosticSnapshot();string before=ContractJson.CanonicalHash(w);Assert.False(NewGameMilitary.HeldAllowed(w,NewMilitaryAction.TakeHeldReply));Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.TakeHeldReply),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    static UnitHeldOrderOutcome Outcome(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.CommandHolding!.Outcomes.Last();
    static void Deliver(WorldSession s){Send(s,NewMilitaryAction.DeliverHeldRecallHome);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);}
    [Fact]public void LateOriginalAppliesOnceButSenderWaitsForActualAck(){var s=Failed();int count=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Deliver(s);var f=Outcome(s);var w=s.DiagnosticSnapshot();Assert.True(f.Received&&f.Applied);Assert.Equal(count+1,w.NewMilitary!.Orders.Length);Assert.False(w.NewMilitary.Withdrawal!.Receipts.Single().Delivered);Assert.Single(w.Messaging.Receipts,r=>r.MessageId==Original(s).Message);Assert.False(MessageFlow.Knows(w.Messaging,f.ReplyMessage!,w.PlayerControl.Value));At(s,f.DueAt);w=s.DiagnosticSnapshot();Assert.True(MessageFlow.Knows(w.Messaging,f.ReplyMessage!,w.PlayerControl.Value));Assert.Contains("遅着原本の受令・実行",NewGameMilitary.PersonalStatus(w));}
    [Fact]public void RetryThenLateOriginalDoesNotRepeatEffect(){var s=Failed();string body=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==Original(s).Message).Body;Send(s,NewMilitaryAction.RetryRecallHome);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Single().DueAt);int count=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Deliver(s);var w=s.DiagnosticSnapshot();Assert.False(Outcome(s).Applied);Assert.Equal(count,w.NewMilitary!.Orders.Length);Assert.Single(w.Messaging.Receipts,r=>r.MessageId==Original(s).Message);Assert.Equal(body,w.Messaging.Messages.Single(m=>m.Id==Original(s).Message).Body);Assert.False(w.NewMilitary.Withdrawal!.Receipts.Single().Delivered);}
    [Fact]public void ConcurrentOriginalAndRetryCreateOneOrder(){var s=Failed();int count=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Send(s,NewMilitaryAction.DeliverHeldRecallHome);Send(s,NewMilitaryAction.RetryRecallHome);long due=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt;At(s,Math.Max(due,s.DiagnosticSnapshot().NewMilitary!.UnitRetry!.Dispatches.Single().DueAt));var w=s.DiagnosticSnapshot();Assert.Equal(count+1,w.NewMilitary!.Orders.Length);Assert.Single(w.Messaging.Receipts,r=>r.MessageId==Original(s).Message);Assert.Single(w.NewMilitary.Orders,o=>o.Id.Value.StartsWith("order:unit-post/"));}
    [Fact]public void NewLocalOrderSuppressesStalePhysicalOriginal(){var s=Failed();Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.Hold);Send(s,NewMilitaryAction.Withdraw);int count=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Deliver(s);Assert.False(Outcome(s).Applied);Assert.Equal(count,s.DiagnosticSnapshot().NewMilitary!.Orders.Length);Assert.Equal(NewMilitaryAction.Hold,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Action);}
    [Fact]public void ActualUnitAbsentRejectsLateOriginalWithoutReceipt(){var s=Failed();Send(s,NewMilitaryAction.Attach);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+30000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);Send(s,NewMilitaryAction.Withdraw);AtPersonEnd(s);Deliver(s);var w=s.DiagnosticSnapshot();Assert.False(Outcome(s).Received);Assert.False(Outcome(s).Applied);Assert.DoesNotContain(w.Messaging.Receipts,r=>r.MessageId==Original(s).Message);Assert.Contains(NewGameMilitary.HeldPapers(w,s.Seconds),h=>h.Attempt==Original(s).Attempt);Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(new WorldSession(ContractJson.Copy(w)).DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void LateOrderAndAckRestoreSameFuture(int phase){var s=Failed();Send(s,NewMilitaryAction.DeliverHeldRecallHome);long due=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt;if(phase>0)At(s,due);if(phase>1)At(s,Outcome(s).DueAt);var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));foreach(var x in new[]{s,c})At(x,due+8);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedLateEffectAckOrBodyIsRejected(int kind){var s=Failed();Deliver(s);At(s,Outcome(s).DueAt);var w=s.DiagnosticSnapshot();var x=w.NewMilitary!.CommandHolding!;if(kind==0)x.Outcomes[0]=x.Outcomes[0] with{Applied=false};if(kind==1)x.Acks[0]=x.Acks[0] with{Received=false};if(kind==2){int n=Array.FindIndex(w.Messaging.Messages,m=>m.Id==x.Outcomes[0].ReplyMessage);w.Messaging.Messages[n]=w.Messaging.Messages[n] with{Body="forged"};}Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void MissedLateAckIsPhysicallyHeldAndRecoverable(){var s=Failed();Deliver(s);var f=Outcome(s);MoveAway(s);At(s,f.DueAt);AtPersonEnd(s);var w=s.DiagnosticSnapshot();Assert.False(w.NewMilitary!.CommandHolding!.Acks.Single().Received);Assert.False(MessageFlow.Knows(w.Messaging,f.ReplyMessage!,w.PlayerControl.Value));Send(s,NewMilitaryAction.PersonalHome);AtPersonEnd(s);int orders=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Send(s,NewMilitaryAction.TakeHeldReply);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);w=s.DiagnosticSnapshot();Assert.True(MessageFlow.Knows(w.Messaging,f.ReplyMessage!,w.PlayerControl.Value));Assert.Equal(orders,w.NewMilitary!.Orders.Length);Assert.False(w.NewMilitary.CommandHolding!.Acks.Single().Received);}
    [Fact]public void PhysicalInquiryQuotesLateOrderEffectWithoutReexecuting(){var s=Failed();Deliver(s);int count=s.DiagnosticSnapshot().NewMilitary!.Orders.Length;Ask(s,NewMilitaryAction.InquireUnitHome);At(s,Query(s).DueAt);var row=Quote(s.DiagnosticSnapshot()).Originals.Single(x=>x.Original==Original(s).Message);Assert.True(row.Received&&row.Applied);Assert.Equal(Outcome(s).At,row.ReceivedAt);Assert.Equal(count,s.DiagnosticSnapshot().NewMilitary!.Orders.Length);}
    static WorldSession FieldFailed(bool reportMissed=false){var s=HomeReady();MoveAway(s);AtPersonEnd(s);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.RemoteRecall) with{OriginalPolicy=NewGameMilitary.UnitCommandHoldingContract},s.PlayerControl,s.Revision).Code);At(s,Original(s).DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single();if(reportMissed){var home=NewGameMilitary.Home(s.DiagnosticSnapshot(),0);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(home.X+10000,home.Y)},s.PlayerControl,s.Revision).Code);}At(s,r.ReplyDueAt);if(reportMissed){AtPersonEnd(s);WalkTo(s,Original(s).Origin);}return s;}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void NonzeroLateOrderAndAcknowledgementRestoreIdenticalPositions(int phase){var s=FieldFailed();Send(s,NewMilitaryAction.DeliverHeldRecallHome);var t=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();Assert.True(t.DueAt>s.Seconds+1&&t.Route.Length>0);if(phase==0)At(s,t.DueAt-1);else{At(s,t.DueAt);var f=Outcome(s);Assert.True(f.DueAt>s.Seconds+1&&f.Route.Length>0);At(s,phase==1?f.DueAt-1:f.DueAt);}var w=s.DiagnosticSnapshot();var c=new WorldSession(ContractJson.Copy(w));Assert.Equal(NewGameMilitary.CourierFrames(w,s.Seconds),NewGameMilitary.CourierFrames(c.DiagnosticSnapshot(),c.Seconds));foreach(var x in new[]{s,c})At(x,t.DueAt+20);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Fact]public void RemainingFailureReportTravelsWithAcknowledgementCarrier(){var s=FieldFailed(true);Assert.Equal(2,NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds).Length);Send(s,NewMilitaryAction.DeliverHeldRecallHome);Assert.Equal(2,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().Cargo.Length);At(s,s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var f=Outcome(s);At(s,f.DueAt-1);var w=s.DiagnosticSnapshot();var held=Assert.Single(NewGameMilitary.HeldPapers(w,s.Seconds));var frame=Assert.Single(NewGameMilitary.CourierFrames(w,s.Seconds));Assert.Equal(f.Carrier,held.Holder);Assert.Equal(frame.Position,held.Position);Assert.NotEqual(f.Origin,held.Position);Assert.False(MessageFlow.FailureKnown(w.Messaging,Original(s).Attempt,w.PlayerControl.Value));At(s,f.DueAt);w=s.DiagnosticSnapshot();Assert.True(MessageFlow.Knows(w.Messaging,f.ReplyMessage!,w.PlayerControl.Value));Assert.False(MessageFlow.FailureKnown(w.Messaging,Original(s).Attempt,w.PlayerControl.Value));}
    [Theory][InlineData(false)][InlineData(true)]public void UnreceivedCourierLabelsDoNotRevealReceiptFailureOrRetry(bool failure){WorldSession s;if(failure){s=FailedReply();var r=Answer(s);Assert.False(MessageFlow.FailureKnown(s.DiagnosticSnapshot().Messaging,r.ReplyAttempt,NewGameMilitary.UnitIds[0].Value));}else{s=FieldFailed();Deliver(s);Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,Outcome(s).ReplyMessage!,s.PlayerControl.Value));}var frames=NewGameMilitary.CourierFrames(s.DiagnosticSnapshot(),s.Seconds);Assert.NotEmpty(frames);foreach(var frame in frames)foreach(var secret in new[]{"受令","不達","再送","実行"})Assert.DoesNotContain(secret,frame.Purpose);}
}
